mapper.update:
{CALL
    DECLARE
        v_sql varchar2(500);
    BEGIN
        v_sql := 'CREATE SEQUENCE ${tableName}_SEQ START WITH 1  MAXVALUE 99999999 MINVALUE 1 CYCLE CACHE 20 NOORDER';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX1 ON ${tableName}(TR_SENDSTAT, TR_SENDDATE)';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX2 ON ${tableName}(TR_PHONE)';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX3 ON ${tableName}(TR_RSLTSTAT, TR_SENDDATE)';
        execute immediate v_sql;
    END
}

{CALL
    DECLARE
        v_sql varchar2(500);
    BEGIN
        v_sql := 'CREATE INDEX ${tableName}_IDX1 ON ${tableName}(TR_PHONE)';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX2 ON ${tableName}(TR_RSLTSTAT, TR_SENDDATE)';
        execute immediate v_sql;
    END
}

UPDATE ${tableName}
SET
    TR_SENDSTAT = CASE WHEN TR_SENDSTAT = '2' THEN TR_SENDSTAT ELSE #{parameter.messageStatus} END,
    TR_MODIFIED = SYSDATE
    , TR_REALSENDDATE = TO_DATE(#{parameter.sentDate}, 'YYYYMMDDHH24MISS')
    , TR_ROUTEID = #{parameter.routeId}
    , TR_RSLTSTAT = #{parameter.doneCode}
    , TR_RSLTDATE = TO_DATE(#{parameter.doneDate}, 'YYYYMMDDHH24MISS')
    , TR_NET = #{parameter.doneTelco}
WHERE
    TR_NUM IS NULL
    TR_NUM = #{parameter.key}

DELETE FROM ${tableName}
WHERE
    TR_NUM IS NULL
    TR_NUM = #{parameter.key}
